    if line.startswith('INSERT INTO'):
        # Extract column list
        match = re.search(r'INSERT INTO \x60(\w+)\x60 \(([^)]+)\) VALUES', line)
        if match:
            table_name = match.group(1)
            col_str = match.group(2)
            cols = [c.strip().strip(chr(96)) for c in col_str.split(',')]
            col_count = len(cols)

            # Count values in next line
            if i < len(lines):
                val_line = lines[i]
                # Simple comma count (rough)
                # Count values by tracking parentheses depth
                vals = []
                current = ''
                depth = 0
                in_str = False
                for ch in val_line:
                    if ch == chr(39):
                        in_str = not in_str
                    if not in_str:
                        if ch == '(':
                            depth += 1
                        elif ch == ')':
                            depth -= 1
                    if ch == ',' and depth == 1 and not in_str:
                        vals.append(current.strip())
                        current = ''
                    elif depth >= 1:
                        current += ch
                if current.strip():
                    vals.append(current.strip())

                if len(vals) != col_count and len(vals) > 0:
                    errors.append(f'Line {i}: {table_name} - columns={col_count}, values={len(vals)}')

if errors:
    print('MISMATCHES FOUND:')
    for e in errors:
        print(f'  {e}')
else:
    print('No mismatches detected')
