const adminSlice = createSlice({
  name: 'admin',
  initialState,
  reducers: {
    // Admin Auth
    setCurrentAdmin: (state, action: PayloadAction<AdminUser>) => {
      state.currentAdmin = action.payload;
    },

    // Stats
    setStats: (state, action: PayloadAction<SystemStats>) => {
      state.stats = action.payload;
